violating:
import * as S from "effect/Schema"

export const ShipmentEvent = S.TaggedUnion({
  Packed: {
    shipmentId: S.String,
    warehouseId: S.String
  },
  Dispatched: {
    shipmentId: S.String,
    trackingNumber: S.String
  },
  Returned: {
    shipmentId: S.String,
    refundCents: S.Number,
    reason: S.String
  }
})

export type ShipmentEvent = typeof ShipmentEvent.Type

export function summarizeReturns(events: ReadonlyArray<ShipmentEvent>) {
  const returns = events.filter((event) => event._tag === "Returned")
  const refundCents = returns.reduce(
    (total, event) => total + event.refundCents,
    0
  )

  return {
    count: returns.length,
    refundCents,
    shipmentIds: returns.map((event) => event.shipmentId)
  }
}

export function trackingLink(event: ShipmentEvent): string | undefined {
  if (ShipmentEvent.guards.Dispatched(event)) {
    return `https://tracking.example.com/${encodeURIComponent(event.trackingNumber)}`
  }
  return undefined
}

